type ApiResult<T> =
  | { kind: "ok"; data: T }
  | { kind: "not-found" }
  | { kind: "invalid"; fieldErrors: Record<string, string> }
  | { kind: "error"; message: string; retryable: boolean };

async function getTodo(id: number): Promise<ApiResult<Todo>> {
  const res = await fetch(`/api/todos/${id}`);
  const body: unknown = await res.json().catch(() => null);
  return interpretResponse({ status: res.status, body }); // pure, easy to test
}

const result = await getTodo(7);
switch (result.kind) {
  case "ok": render(result.data); break;
  case "not-found": showEmptyState(); break;
  case "invalid": showErrors(result.fieldErrors); break;
  case "error": if (result.retryable) scheduleRetry(); break;
}
